&lt;div
  class="contact-visual-rectangle"
  role="img"
  aria-label="Contact page visual"&gt;
&lt;/div&gt;


&lt;div class="contact-kicker"&gt;CONTACT&lt;/div&gt;

&lt;form
  action="https://formsubmit.co/eebrahimi.bio@gmail.com"
  method="POST"
  class="contact-form"&gt;

  &lt;input
    type="hidden"
    name="_subject"
    value="New message from BioGeoAI website"&gt;

  &lt;input
    type="hidden"
    name="_captcha"
    value="false"&gt;

  &lt;input
    type="hidden"
    name="_template"
    value="table"&gt;

  &lt;div class="contact-grid"&gt;

    &lt;div class="field-group"&gt;
      &lt;label for="name"&gt;NAME&lt;/label&gt;
      &lt;input
        type="text"
        id="name"
        name="name"
        autocomplete="name"
        required&gt;
    &lt;/div&gt;

    &lt;div class="field-group"&gt;
      &lt;label for="email"&gt;EMAIL&lt;/label&gt;
      &lt;input
        type="email"
        id="email"
        name="email"
        autocomplete="email"
        required&gt;
    &lt;/div&gt;

  &lt;/div&gt;

  &lt;div class="field-group message-group"&gt;

    &lt;label for="message"&gt;MESSAGE&lt;/label&gt;

    &lt;textarea
      id="message"
      name="message"
      rows="8"
      required&gt;&lt;/textarea&gt;

  &lt;/div&gt;

  &lt;button
    type="submit"
    class="contact-submit"
    aria-label="Send message"&gt;
    ↗
  &lt;/button&gt;

&lt;/form&gt;
